export function findCatalogStation(stationRef) {
  const match = String(stationRef || "").match(/^catalog:([^:]+):(\d+)$/);
  if (!match) return null;
  const station = RADIO_CATALOG[match[1]]?.[Number(match[2])];
  return station ? { ...station } : null;
}

